/ {
	chosen {
		zephyr,entropy = &test_entropy;
		zephyr,flash = &test_flash;
		zephyr,flash-controller = &test_flash_ctrl;
		zephyr,console = &test_serial;
		zephyr,shell-uart = &test_serial;
		zephyr,uart-pipe = &test_serial;
		zephyr,bt-hci = &test_bt_hci;
		zephyr,bt-mon-uart = &test_serial;
		zephyr,tracing-uart = &test_serial;
		zephyr,sram = &test_sram0;
		zephyr,code-partition = &slot0_partition;
	};

	leds {
		compatible = "gpio-leds";
		led0: led_0 {
			gpios = <&test_gpio 4 0>;
			label = "LED 0";
		};
	};

	aliases {
		test-fixed-part = &test_fixed_part;
		test-i2c = &test_i2c;
		test-spi = &test_spi;
		test-uart = &test_serial;
		test-gpio = &test_gpio;
	};

	test_pinctrl: pinctrl {
		compatible = "vnd,pinctrl";
		#address-cells = <1>;
		#size-cells = <0>;

		test_pincfg_a: pincfg-a {
			reg = <0>;
		};

		test_pincfg_b: pincfg-b {
			reg = <1>;
		};

		test_pincfg_c: pincfg-c {
			reg = <2>;
		};

		test_pincfg_d: pincfg-d {
			reg = <3>;
		};

		test_pincfg_e: pincfg-e {
			reg = <4>;
		};
	};

	test_i2c: i2c@0 {
		compatible = "vnd,i2c";
		reg = <0 0>;
		#address-cells = <1>;
		#size-cells = <0>;

		test_temp: temp-sensor@0 {
			compatible = "vnd,temp-sensor";
			reg = <0>;
			pinctrl-names = "default", "sleep", "foo";
			pinctrl-0 = <&test_pincfg_a &test_pincfg_b>;
			pinctrl-1 = <&test_pincfg_c>;
			pinctrl-2 = <&test_pincfg_d &test_pincfg_e>;
		};
	};

	test_spi: spi@1 {
		compatible = "vnd,spi";
		reg = <1 0>;
		#address-cells = <1>;
		#size-cells = <0>;

		test_eeprom: eeprom@0 {
			compatible = "vnd,eeprom";
			reg = <0>;
			size = <256>;
		};
	};

	test_serial: serial@2 {
		compatible = "vnd,serial";
		reg = <2 0>;
		current-speed = <115200>;
	};

	test_gpio: gpio@3 {
		compatible = "vnd,gpio";
		reg = <3 0>;
		gpio-controller;
		#gpio-cells = <2>;
	};

	test_sram0: sram@4 {
		compatible = "mmio-sram";
		reg = <4 0x1000>;
	};

	test_sram1: sram@5 {
		compatible = "mmio-sram";
		reg = <5 0x1000>;
	};

	test_flash_ctrl: flash-controller@6 {
		compatible = "vnd,flash-controller";
		reg = <6 0>;
		#address-cells = <1>;
		#size-cells = <1>;

		test_flash: flash@0 {
			compatible = "soc-nv-flash";
			reg = <0 0x4000>;
			erase-block-size = <512>;
			write-block-size = <4>;

			partitions {
				compatible = "fixed-partitions";
				#address-cells = <1>;
				#size-cells = <1>;

				test_fixed_part: partition@0 {
					reg = <0 0x1000>;
				};

				slot0_partition: partition@1000 {
					reg = <0x1000 0x1000>;
				};
			};
		};
	};

	test_entropy: entropy@7 {
		compatible = "vnd,entropy";
		reg = <7 0>;
	};

	test_bt_hci: bt_hci@8 {
		compatible = "vnd,bt-hci";
		reg = <8 0>;
	};

	test_phandles {
		a = <1 2 &test_serial 4>;
		b = <&test_i2c>;
		c;
	};

	test_noderef {
		a = <&test_i2c>;
		b = <&test_spi>;
		c;
	};

	test_props {
		a = "foo";
		b = <1 2>;
		c;
		d = <0xdeadbeef>;
		e = [de ad be ef];
		f = "bar", "baz";
		g = <&test_i2c>;
		h = <&test_i2c>, <&test_spi>;
		i = <&test_i2c 0 1>, <&test_spi 2 3>;
	};

	test_reg {
		reg = <0 1 2 3>, <4 5 6 7>;
		reg-names = "a", "b";
	};

	test_interrupts {
		interrupts = <1 2 3 4>, <5 6 7 8>;
		interrupt-names = "a", "b";
		interrupt-parent = <&test_gpio>;
	};

	test_pwms {
		pwms = <&test_pwm1 0 1>, <&test_pwm2 2 3>;
		pwm-names = "a", "b";
	};

	test_iochannels {
		io-channels = <&test_adc1 0>, <&test_adc2 1>;
		io-channel-names = "a", "b";
	};

	test_gpios {
		gpios = <&test_gpio 0 1>, <&test_gpio 2 3>;
		gpio-names = "a", "b";
	};

	test_clocks {
		clocks = <&test_clock1 0>, <&test_clock2 1>;
		clock-names = "a", "b";
	};

	test_resets {
		resets = <&test_reset1 0>, <&test_reset2 1>;
		reset-names = "a", "b";
	};

	test_mboxes {
		mboxes = <&test_mbox1 0>, <&test_mbox2 1>;
		mbox-names = "a", "b";
	};

	test_dmas {
		dmas = <&test_dma1 0>, <&test_dma2 1>;
		dma-names = "a", "b";
	};

	test_mmio_sram {
		mmio-sram = <&test_sram0>, <&test_sram1>;
		mmio-sram-names = "a", "b";
	};

	test_power_domains {
		power-domains = <&test_pd1>, <&test_pd2>;
		power-domain-names = "a", "b";
	};

	test_memory_region {
		memory-region = <&test_sram0>, <&test_sram1>;
		memory-region-names = "a", "b";
	};

	test_interrupt_map {
		interrupt-map = <1 2 &test_gpio 3 4>, <5 6 &test_gpio 7 8>;
	};

	test_child {
		#address-cells = <1>;
		#size-cells = <1>;

		test_child_child: child@0 {
			reg = <0 1>;
		};
	};

	test_ord {
		a: a {
			ord = <2>;
		};
		b: b {
			ord = <0>;
		};
		c: c {
			ord = <1>;
		};
	};

	/delete-node/ &test_i2c;
};

&test_i2c {
	status = "okay";
};

&test_spi {
	status = "okay";
};

&test_serial {
	status = "okay";
};

&test_gpio {
	status = "okay";
};

&test_sram0 {
	status = "okay";
};

&test_sram1 {
	status = "okay";
};

&test_flash_ctrl {
	status = "okay";
};

&test_entropy {
	status = "okay";
};

&test_bt_hci {
	status = "okay";
};
